#include <math.h>

int main() {
    double cx, cy, r, px, py;
    scanf("%lf %lf %lf", &cx, &cy, &r);
    scanf("%lf %lf", &px, &py);

    double dx = px - cx;
    double dy = py - cy;
    double d_sq = dx*dx + dy*dy;
    double d = sqrt(d_sq);

    if (d < r) {
        printf("No tangents\n");
        return 0;
    }

    if (fabs(d - r) < 1e-12) {
        // Point is exactly on the circle: one tangent point = the point itself
        printf("%.10f %.10f\n", px, py);
        return 0;
    }

    double angle = atan2(dy, dx);
    double alpha = acos(r / d);

    double t1x = cx + r * cos(angle + alpha);
    double t1y = cy + r * sin(angle + alpha);
    double t2x = cx + r * cos(angle - alpha);
    double t2y = cy + r * sin(angle - alpha);

    // Sort output by x then y
    if (t1x < t2x || (fabs(t1x - t2x) < 1e-12 && t1y < t2y)) {
        printf("%.10f %.10f\n", t1x, t1y);
        printf("%.10f %.10f\n", t2x, t2y);
    } else {
        printf("%.10f %.10f\n", t2x, t2y);
        printf("%.10f %.10f\n", t1x, t1y);
    }

    return 0;
}

