int main(void) {
    double px, py, cx, cy, r;
    if (scanf("%lf %lf %lf %lf %lf", &px, &py, &cx, &cy, &r) != 5) {
        return 0;
    }

    const double EPS = 1e-12;

    double dx = px - cx;
    double dy = py - cy;
    double d2 = dx * dx + dy * dy;
    double d = sqrt(d2);

    /* No tangent if point is strictly inside the circle */
    if (d < r - EPS) {
        return 0;
    }

    /* Point on the circle: exactly one tangent line */
    if (fabs(d - r) <= EPS) {
        /* Tangent direction is perpendicular to radius */
        double tx = -dy;
        double ty = dx;

        /* Line through P and tangent point P itself */
        /* Output as two points on the line */
        printf("%.10f %.10f %.10f %.10f\n", px, py, px + tx, py + ty);
        return 0;
    }

    /* Two tangents */
    double alpha = atan2(dy, dx);
    double beta = acos(r / d);

    for (int s = -1; s <= 1; s += 2) {
        double ang = alpha + s * beta;
        double tx = cx + r * cos(ang);
        double ty = cy + r * sin(ang);
        printf("%.10f %.10f %.10f %.10f\n", px, py, tx, ty);
    }

    return 0;
}

