#include <bits/stdc++.h>
using namespace std;

/*
  Tangent lines from a point P to a circle with center C and radius r.

  A line through P with direction d = (dx, dy) is tangent to the circle iff
  the distance from center C to the line equals r.

  Let v = C - P.
  For a unit direction d, distance from C to the line through P along d is
      |cross(v, d)| = r
  and |d| = 1.

  If D = |v|:
    - D < r : no tangents
    - D = r : one tangent, perpendicular to v
    - D > r : two tangents

  We can construct unit directions:
      d = (v * a) ± perp(v) * b
  where
      a = sqrt(D^2 - r^2) / D^2
      b = r / D^2
  equivalently:
      d = normalize(v) * cos(theta) ± perp(normalize(v)) * sin(theta)
      with sin(theta) = r / D

  Then line is represented by two points: P and P + d.
*/

static const double EPS = 1e-10;

struct Point {
    double x, y;
    Point() {}
    Point(double x_, double y_) : x(x_), y(y_) {}
    Point operator + (const Point& other) const { return Point(x + other.x, y + other.y); }
    Point operator - (const Point& other) const { return Point(x - other.x, y - other.y); }
    Point operator * (double k) const { return Point(x * k, y * k); }
};

double dot(const Point& a, const Point& b) { return a.x * b.x + a.y * b.y; }
double norm2(const Point& a) { return dot(a, a); }
double norm(const Point& a) { return sqrt(norm2(a)); }
Point perp(const Point& a) { return Point(-a.y, a.x); }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double px, py, cx, cy, r;
    cin >> px >> py >> cx >> cy >> r;

    Point P(px, py), C(cx, cy);
    Point v = C - P;
    double d2 = norm2(v);
    double d = sqrt(d2);

    cout << fixed << setprecision(12);

    if (d + EPS < r) {
        cout << 0 << '\n';
        return 0;
    }

    vector<pair<Point, Point>> ans;

    if (fabs(d - r) <= EPS) {
        Point dir = perp(v);
        double len = norm(dir);
        if (len > EPS) dir = dir * (1.0 / len);
        ans.push_back({P, P + dir});
    } else {
        double a = sqrt(d2 - r * r) / d2;
        double b = r / d2;

        Point pv = perp(v);

        Point d1 = v * a + pv * b;
        Point d2p = v * a - pv * b;

        ans.push_back({P, P + d1});
        ans.push_back({P, P + d2p});
    }

    cout << ans.size() << '\n';
    for (auto &ln : ans) {
        cout << ln.first.x << ' ' << ln.first.y << ' '
             << ln.second.x << ' ' << ln.second.y << '\n';
    }

    return 0;
}

import java.util.Scanner;

public class TangentLines {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        double px = sc.nextDouble();
        double py = sc.nextDouble();
        double cx = sc.nextDouble();
        double cy = sc.nextDouble();
        double r = sc.nextDouble();

        double dx = px - cx;
        double dy = py - cy;
        double d = Math.sqrt(dx * dx + dy * dy);

        if (d < r) {
            System.out.println("No tangents (point inside circle)");
            return;
        }

        if (Math.abs(d - r) < 1e-12) {
            // Point is on the circle, tangent is perpendicular to radius
            double tx = px - dx;
            double ty = py - dy;
            System.out.printf("%.10f %.10f%n", tx, ty);
            return;
        }

        double angle = Math.acos(r / d);
        double baseAngle = Math.atan2(dy, dx);

        double angle1 = baseAngle + angle;
        double angle2 = baseAngle - angle;

        double tx1 = cx + r * Math.cos(angle1);
        double ty1 = cy + r * Math.sin(angle1);
        double tx2 = cx + r * Math.cos(angle2);
        double ty2 = cy + r * Math.sin(angle2);

        // Sort output for consistency
        if (tx1 < tx2 || (Math.abs(tx1 - tx2) < 1e-12 && ty1 < ty2)) {
            System.out.printf("%.10f %.10f%n", tx1, ty1);
            System.out.printf("%.10f %.10f%n", tx2, ty2);
        } else {
            System.out.printf("%.10f %.10f%n", tx2, ty2);
            System.out.printf("%.10f %.10f%n", tx1, ty1);
        }
    }
}

