import java.io.*;
import java.util.*;

/*
 * Tangents from a point to a circle.
 *
 * Input format (assumed standard geometric form):
 *   px py
 *   cx cy r
 *
 * Output:
 *   If no tangent exists: 0
 *   If exactly one tangent exists: 1, then the tangent point
 *   If two tangents exist: 2, then the two tangent points
 *
 * Each tangent line from point P to circle C is uniquely determined by its
 * tangent point T on the circle, so outputting tangent points is sufficient.
 *
 * Geometry:
 * Let P be the external point, O the circle center, radius r.
 * For tangent point T:
 *   |OT| = r, and OT ⟂ PT.
 * In triangle OPT, with d = |OP|,
 *   projection length from O toward P is a = r^2 / d
 *   perpendicular offset is h = r * sqrt(d^2 - r^2) / d
 *
 * If u = (P - O) / d, and perp(u) = (-uy, ux),
 * tangent points are:
 *   T = O + u * a ± perp(u) * h
 *
 * Special cases:
 *   d < r  -> no tangents
 *   d = r  -> one tangent (the point itself)
 *   d > r  -> two tangents
 */

public class Main {
    static final double EPS = 1e-10;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 1;
                c = read();
                while (c >= '0' && c <= '9') {
                    mul /= 10.0;
                    val += (c - '0') * mul;
                    c = read();
                }
            }

            return val * sign;
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    static String fmt(double v) {
        if (Math.abs(v) < 5e-13) v = 0;
        return String.format(Locale.US, "%.10f", v);
    }

    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        FastScanner fs = new FastScanner(System.in);

        double px, py, cx, cy, r;
        try {
            px = fs.nextDouble();
            py = fs.nextDouble();
            cx = fs.nextDouble();
            cy = fs.nextDouble();
            r = fs.nextDouble();
        } catch (Exception e) {
            return;
        }

        double dx = px - cx;
        double dy = py - cy;
        double d2 = dx * dx + dy * dy;
        double r2 = r * r;

        StringBuilder out = new StringBuilder();

        if (d2 < r2 - EPS) {
            out.append("0\n");
        } else if (Math.abs(d2 - r2) <= EPS) {
            out.append("1\n");
            out.append(fmt(px)).append(' ').append(fmt(py)).append('\n');
        } else {
            double d = Math.sqrt(d2);
            double ux = dx / d;
            double uy = dy / d;

            double a = r2 / d;
            double h = r * Math.sqrt(d2 - r2) / d;

            double baseX = cx + ux * a;
            double baseY = cy + uy * a;

            double perpx = -uy;
            double perpy = ux;

            Point t1 = new Point(baseX + perpx * h, baseY + perpy * h);
            Point t2 = new Point(baseX - perpx * h, baseY - perpy * h);

            // Deterministic order
            if (t1.x > t2.x + EPS || (Math.abs(t1.x - t2.x) <= EPS && t1.y > t2.y + EPS)) {
                Point tmp = t1; t1 = t2; t2 = tmp;
            }

            out.append("2\n");
            out.append(fmt(t1.x)).append(' ').append(fmt(t1.y)).append('\n');
            out.append(fmt(t2.x)).append(' ').append(fmt(t2.y)).append('\n');
        }

        System.out.print(out.toString());
    }
}
